// Hand-written from the API contract in CLAUDE.md.
// Once the FastAPI backend exists, replace with types generated by `npm run gen:api`.

/** A question's language: Uzbek and Russian in Uzbekistan, Russian or English for other countries (since 16 Nov 2026). */
export type PromptLanguage = "uz" | "ru" | "en";

export type Tone = "positive" | "neutral" | "negative";

export type ReportPeriod = "week";

export interface Brand {
  id: string;
  name: string;
  /** Other spellings, Latin and Cyrillic, e.g. "Oq Tabassum", "Ок Табассум". */
  aliases: string[];
  domain: string;
  /**
   * The brand's logo, an image address we serve: the backend finds it on the brand's website (its icon or
   * the logo it declares) when the brand is added, and keeps a copy. Absent or null when none was found:
   * the brand's first letter stands in.
   */
  logo?: string | null;
}

/** The paid plans (names in messages/Plans). The free check has no project. */
export type Plan = "start" | "business" | "agency";

/** What the project's plan allows. */
export interface ProjectLimits {
  /**
   * Questions the project may track at once; archived ones don't count. On the agency plan the plan's questions
   * are shared by the agency's brands, and this is what this brand may use.
   */
  prompts: number;
  /** Competitors it may track. */
  competitors: number;
  /** Brand facts it may keep for the answers to be checked against (Sozlamalar › Faktlar). */
  facts: number;
}

export interface Project {
  id: string;
  brand: Brand;
  competitors: Brand[];
  category: string;
  /** The free first check it was saved from, whose Free Snapshot is `/snapshot/{firstRunId}` (a real project, 0.8). */
  firstRunId?: string | null;
  /** "" when the business serves its whole country. */
  city: string;
  /** Two-letter country code; left out by sample data, which is Uzbekistan's. */
  country?: string;
  /** The questions that name the business, asked at every check; absent in sample data. */
  brandQuestions?: BrandQuestion[];
  languages: PromptLanguage[];
  /** The brand profile from onboarding: a sentence or two on the business ("" if none). */
  description: string;
  /** What the business offers, as the client wrote it ("Implantlar", "Breketlar"); steers suggested questions. */
  services: string[];
  /** Who buys it, as the client wrote it in Discovery ("Ota-onalar", "Tishi ogʻriyotganlar"); steers suggested questions too. */
  customers: string[];
  /** Words the brand wants to be known by ("Oilaviy", "Ogʻriqsiz"), Peec's brand identity; steers suggested questions too. */
  identity: string[];
  plan: Plan;
  limits: ProjectLimits;
  billing: ProjectBilling;
}

/**
 * How the plan is paid (Stripe since 22 Nov 2026, `backend/app/billing.py`): monthly or for a year ahead, and when the
 * period paid for ends.
 */
export interface ProjectBilling {
  cycle: BillingCycle;
  renewsAt: string | null;
  /**
   * "trial": the 7 days after the free first check (its report stays; nothing more is checked until a plan is paid);
   * "trial_ended": past them, unpaid; "active": paid up, checked on its plan's days; "unpaid": a payment failed, the
   * checks paused until it goes through; "canceled": the subscription ended. Absent means active (sample data).
   */
  status?: BillingStatus;
  /** When the trial's 7 days end. */
  trialEndsAt?: string | null;
  /** When a cancellation takes effect: paid until then. */
  cancelsAt?: string | null;
  /** Stripe's checkout can be opened (the backend has its key); otherwise a plan is asked for and switched on by hand. */
  online?: boolean;
  /** Stripe's billing page can be opened: the project has a Stripe customer. */
  portal?: boolean;
}

export type BillingStatus = "trial" | "trial_ended" | "active" | "unpaid" | "canceled";

/** Stripe's checkout for Standard or Pro (`POST /projects/{id}/checkout`); answered with the page's address. */
export interface CheckoutRequest {
  plan: "start" | "business";
  cycle: BillingCycle;
  /** The language of the page Stripe sends the customer back to. */
  language: "uz" | "ru" | "en";
}

/** An address on Stripe to send the browser to: its checkout or its billing page. */
export interface StripePage {
  url: string;
}

export type BillingCycle = "month" | "year";

export interface Prompt {
  id: string;
  text: string;
  language: PromptLanguage;
  topic: string;
  /** ISO 8601: when it was added. Its results start with the first run after that. */
  createdAt: string;
  /**
   * ISO 8601: when the client stopped tracking it; null while it is tracked. An archived question isn't
   * asked any more and is left out of the report, keeps its past answers (its own page still shows them),
   * and doesn't count toward the plan's limit. It can be tracked again.
   */
  archivedAt: string | null;
  /**
   * The city it is asked from, a key of messages/Cities: the web search answers as it would someone there
   * (the search tool's approximate user location). The project's city unless the client chose another.
   */
  location: string;
  /** Whether its answers are checked against the brand's facts for wrong ones (Peec's fact-checking switch); on for a new question. */
  factCheck: boolean;
  /** The client's own labels on it, beside its topic: a branch, a campaign. */
  tags: string[];
}

export interface ReportMethod {
  engine: string;
  model: string;
  webSearch: boolean;
  /** Answers collected per prompt. */
  samples: number;
  /** ISO 8601 timestamp. */
  collectedAt: string;
}

export interface BrandScore {
  brandId: string;
  /** Answers naming the brand / all answers, 0–1. */
  visibility: number;
  /** Mentions of the brand / mentions of all tracked brands, 0–1. */
  shareOfVoice: number;
  /** Mean position (1 = first) over answers naming the brand; null if never named. */
  avgPosition: number | null;
  /** Mean tone of the brand's mentions, 0–100 (positive 100, neutral 50, negative 0); null if never named. */
  sentiment: number | null;
  /** Change in visibility vs the previous period, e.g. 0.05 = +5 points. */
  trend: number;
}

export interface Mention {
  brandId: string;
  /** 1 = first clinic named in the answer. */
  position: number;
  tone: Tone;
  /** Whether the answer recommends the brand, not only names it. Sent by a first run; absent elsewhere. */
  recommended?: boolean;
}

export interface Citation {
  url: string;
  domain: string;
  /** The page's title, as the search tool reports it with the link; null when it gives none. */
  title: string | null;
}

export interface Answer {
  /** 1-based sample number. */
  sample: number;
  text: string;
  mentions: Mention[];
  citations: Citation[];
  /**
   * The web searches ChatGPT ran before writing the answer, as the search tool reports them, in order.
   * Empty when it answered without searching.
   */
  searches: string[];
  /** The assistant that gave the answer ("chatgpt", "gemini"). Sent by a first run; absent elsewhere. */
  engine?: string;
}

export interface PromptResult {
  prompt: Prompt;
  answers: Answer[];
}

/**
 * own: the brand's website; competitor: a tracked competitor's website; news: news sites;
 * directory: maps, catalogs and review sites; social: social networks and Telegram channels.
 */
export type SourceType = "own" | "competitor" | "news" | "directory" | "social" | "other";

/**
 * A cited site's type by the report spec (§4.6, Phase 0 item 0.4). The report reads these; the app's other pages
 * still show the six `SourceType` kinds, which the backend works out from them.
 */
export type DomainType =
  | "client_owned"
  | "client_managed"
  | "competitor_site"
  | "directory"
  | "media"
  | "ugc"
  | "telegram"
  | "reference"
  | "platform_docs"
  | "unclassified";
/** Who controls what a site says of the client. */
export type DomainControl = "owned" | "managed" | "earned" | "not_addressable";
/** Who typed a site: our seed list or the project's own sites, the AI, or a person. */
export type DomainReview = "seed" | "automated" | "founder-reviewed";
/** How a business gets onto a site: only from our checked list or a person's review, never from the AI. */
export interface DomainRoute {
  how: "listing_page" | "form" | "editor_contact";
  url: string;
}

export interface CitedPage {
  url: string;
  /** The page's title, as it was cited; null when unknown. */
  title: string | null;
  /** How many answers cited this page. */
  count: number;
  /** Tracked brands (ids) the page names, found by reading it; null when it couldn't be read. */
  mentions: string[] | null;
}

export interface Source {
  domain: string;
  type: SourceType;
  /** How many answers cited this domain. */
  count: number;
  /** Whether the project's brand is listed on this source. */
  brandListed: boolean;
  /** The domain's pages the answers cite, most cited first. */
  pages: CitedPage[];
  /** Its type by the report spec, who controls it, the route onto it, who typed it (a real project's report). */
  domainType?: DomainType;
  control?: DomainControl;
  route?: DomainRoute | null;
  review?: DomainReview;
  /** The tracked competitors beside it: named in the answers citing it, or on its pages once read. */
  rivals?: string[];
}

export interface WrongFact {
  claim: string;
  correct: string;
  /** "" when it comes from a brand question: `question` and `engine` then say where it was said. */
  promptId: string;
  /** From a brand answer: the claim and what the website says, in the interface's three languages. */
  texts?: { claim: ThreeLanguages; correct: ThreeLanguages };
  question?: string | null;
  engine?: string | null;
  /** ISO 8601 timestamp of the run that first found it. */
  foundAt: string;
}

/** One finished run: how many of its answers cited each site, and each page of the site. */
export interface SourceHistoryPoint {
  /** ISO 8601 timestamp. */
  collectedAt: string;
  /** Answers of that run: what a count is a share of. */
  answers: number;
  /** The sites cited in that run, each with its kind; one that wasn't cited is left out. */
  sources: { domain: string; type: SourceType; count: number; pages: { url: string; count: number }[] }[];
}

/** One finished run: every tracked brand's scores at that time. */
export interface HistoryPoint {
  /** The run's id: its own report is `GET /projects/{id}/reports/{runId}` (Hisobotlar). */
  runId: string;
  /** ISO 8601 timestamp. */
  collectedAt: string;
  scores: Omit<BrandScore, "trend">[];
  /** The run's answers, and those that name the client: the count Hisobotlar and the project cards show (no score since 21 Nov 2026). */
  answers: number;
  named: number;
}

/**
 * The five areas a report reads the client on, each by its own counts (Phase 0 item 0.2, 21 Nov 2026: no score
 * and no status any more): visibility: the answers naming it; competition: where it stands among the tracked
 * brands; coverage: the questions that name it at all; sources: how often its site is cited; accuracy: how it
 * is spoken of, and what is said of it that is wrong.
 */
export type ReportArea = "visibility" | "competition" | "coverage" | "sources" | "accuracy";

/**
 * A change to the project's brand profile (Sozlamalar › Profil): any of the fields, the rest stay. The
 * name, spellings and website change what counts as the brand from the next check; the profile steers the
 * suggested questions, which are written again.
 */
export interface UpdateProjectRequest {
  name?: string;
  domain?: string;
  aliases?: string[];
  description?: string;
  category?: string;
  city?: string;
  country?: string;
  services?: string[];
  customers?: string[];
  identity?: string[];
  /** The questions that name the business, replaced as a whole (Sozlamalar › Brend savollari). */
  brandQuestions?: BrandQuestion[];
}

/** A change to a tracked competitor (Sozlamalar › Brendlar): its name, its spellings, its website. */
export type UpdateBrandRequest = Partial<Pick<Brand, "name" | "aliases" | "domain">>;

/** The project's brand facts, one statement each, replaced as a whole (Sozlamalar › Faktlar). */
export interface FactsRequest {
  facts: string[];
}

/** A tag of the project's questions, with how many tracked questions carry it (Sozlamalar › Teglar). */
export interface TagSummary {
  name: string;
  prompts: number;
}

/** New tags, several at once; a name the project has already is skipped. */
export interface CreateTagsRequest {
  names: string[];
}

/** Someone with access to the account's projects (Sozlamalar › A'zolar). */
export interface Member {
  id: string;
  name: string | null;
  /** E.164; null for someone who joined with Telegram. */
  phone: string | null;
  telegramUsername: string | null;
  /** The owner pays and can't be removed; members see and change the projects. */
  role: "owner" | "member";
  /** Invited: the SMS with the link was sent and they haven't logged in yet. */
  status: "active" | "invited";
  /** The projects they can open. */
  projectIds: string[];
}

/** An invitation by phone number: the backend sends an SMS with a link to log in. */
export interface InviteMemberRequest {
  phone: string;
}

/** A request to change the plan, or to cancel it. Billing isn't built: it reaches us, and we change the plan by hand. */
export interface PlanRequest {
  plan: Plan | "managed" | "cancel";
  /** Paid monthly or for a year ahead; the project's own cycle when left out. */
  cycle?: BillingCycle;
}

/** A change to the logged-in user (Sozlamalar › Umumiy). */
export interface UpdateMeRequest {
  name: string;
}

/** A brand the answers name that the project doesn't track: a possible new competitor. */
export interface UntrackedBrand {
  name: string;
  /** How many answers named it. */
  answers: number;
  /** The client hid it from the suggestions (it isn't a competitor); it can be shown again. */
  dismissed: boolean;
}

/**
 * listing: get onto a site ChatGPT relies on; fact: correct something ChatGPT gets wrong; content: publish
 * a page that answers questions where the brand is missing; technical: a fix on the brand's own website.
 */
export type ActionKind = "listing" | "fact" | "content" | "technical";

/** new: suggested; in_progress: the client took it on; done: the client says it's done; declined: not doing it. */
export type ActionStatus = "new" | "in_progress" | "done" | "declined";

/** Expected effect on visibility, compared with the project's other actions. */
export type ActionImpact = "high" | "medium" | "low";

/** Checks the backend runs on the brand's website; the last six are the SEO audit of 23 Nov 2026. */
export type SiteCheck =
  | "ai_bots_blocked"
  | "prices_as_images"
  | "no_business_markup"
  | "contacts_missing"
  | "no_prices"
  | "no_faq"
  | "no_sitemap"
  | "no_llms_txt"
  | "weak_meta"
  | "one_language"
  /** Almost no words read: the pages show their text only with JavaScript, which most AI crawlers don't run (25 Nov 2026). */
  | "js_only";

/** One check on the brand's website; `passed` false means the problem was found. */
export interface SiteCheckResult {
  check: SiteCheck;
  passed: boolean;
}

interface ActionBase {
  id: string;
  status: ActionStatus;
  impact: ActionImpact;
  /** The questions it should improve, most affected first. */
  promptIds: string[];
  /** ISO 8601: the run that suggested it. */
  createdAt: string;
  /** ISO 8601: when it was marked done; null otherwise. */
  doneAt: string | null;
  /** The how-to steps the client has checked off, by index (0 = first), ascending; a half-done fix shows where it stopped. */
  stepsDone: number[];
  /**
   * Fix → proof: the brand's visibility (0–1) on `promptIds` in the last run before it was done, and
   * in the latest run, `runs` runs later. Null until a run has finished since it was done.
   */
  proof: {
    before: number;
    after: number;
    runs: number;
    /** The answers naming the brand, of the answers to `promptIds`, in each of the two runs: what the report shows each share beside. */
    counts: { before: [number, number]; after: [number, number] };
  } | null;
}

/** What a page of the client's website is, for an action that reworks it. */
export type PageType = "home" | "service" | "prices" | "article" | "about" | "other";

/**
 * What to write, for an action that writes or reworks a page, as Peec's brief: the backend writes it
 * with a model from the answers that name competitors and not the client.
 */
export interface ContentBrief {
  /** What the page is and whom it is for. */
  summary: string;
  /** Titles to choose from. */
  headlines: string[];
  /** The page's title for search engines and AI; the frontend counts it against 60 characters. */
  metaTitle: string;
  /** Its description; counted against 155. */
  metaDescription: string;
  /** The one thing the page must make clear. */
  argue: string;
  /** Facts the page should show: prices, years, names, numbers. */
  proofPoints: string[];
}

/** A recommended fix, made from the weekly report. Steps are written by the frontend from `kind` and its fields. */
export type Action = ActionBase &
  (
    | {
        kind: "listing";
        domain: string;
        sourceType: SourceType;
        /** The site's type by the report spec and the way onto it (a real project, since Phase 0 item 0.4). */
        domainType?: DomainType;
        route?: DomainRoute | null;
        /** Answers citing the site. */
        answers: number;
        /** Tracked competitors named in those answers, most named first. */
        competitorIds: string[];
      }
    | { kind: "fact"; claim: string; correct: string }
    | {
        kind: "content";
        topic: string;
        /** A page of the client's to rework (made with "Add content"); null for a page to write. */
        url: string | null;
        pageType: PageType | null;
        brief: ContentBrief | null;
        /** What the rivals' cited pages state for its questions and the client's site doesn't (the research). */
        missing?: (MissingFact & { rival: string; url: string | null })[];
      }
    | { kind: "technical"; check: SiteCheck }
  );

export interface User {
  id: string;
  /** From Telegram; null for accounts made with a phone number. */
  name: string | null;
  /** What the account logs in with: a code is sent to it. Null only for an account from before email login. */
  email: string | null;
  /** E.164, e.g. "+998901234567". Login is by email now, so the backend sends null. */
  phone: string | null;
  telegramUsername: string | null;
  /** The pages' guided tours this account has seen (`PageTour` ids): none starts by itself again, on any device. */
  seenTours?: string[];
}

export interface Report {
  project: Project;
  period: ReportPeriod;
  method: ReportMethod;
  scores: BrandScore[];
  prompts: PromptResult[];
  topSources: Source[];
  wrongFacts: WrongFact[];
  /**
   * False when nobody checked this run's answers against the brand's facts (no facts given, a plan without
   * the check, or a run from before it existed): an empty `wrongFacts` then means "not checked", never
   * "none found". Absent means checked.
   */
  factsChecked?: boolean;
  /** What each assistant said of the business by name at this check; absent in sample data. */
  brandView?: BrandView[];
  /** The assistants that answered in the latest check, whichever the report is filtered to; absent in sample data. */
  engines?: ReportEngine[];
  /** Past runs, oldest first, ending with this one (a single point after the first run). */
  history: HistoryPoint[];
  /** The cited sites over the same runs, oldest first, ending with this one (whose counts are `topSources`). */
  sourceHistory: SourceHistoryPoint[];
  /** Brands named in the answers but not tracked, most named first. */
  untrackedBrands: UntrackedBrand[];
  /** ISO 8601: when the project's questions are asked again (runs are weekly); null when nothing is scheduled. */
  nextRunAt: string | null;
  /** Why AI names others and not the client, per lost question of the check shown (report spec §4.5); null until researched. */
  research?: ResearchFinding[] | null;
}

/**
 * One lost question researched (23 Nov 2026, `backend/app/research.py`): the business an answer named, the sentence it
 * said about it (cut from the answer), the page it cited for it beside the client's closest page, the facts that page
 * states and the client's doesn't, each with its quote, and a section the client could put on its page. Every quote is
 * checked against its page; `automated` until the founder reviews it.
 */
export interface ResearchFinding {
  promptId: string;
  question: string;
  language: PromptLanguage;
  engine: string;
  rival: { name: string; tracked: boolean };
  sentence: string;
  review: "automated" | "founder-reviewed";
  /**
   * compared; no_page: the answer cited no page of the business's own; unreadable: its page couldn't be read;
   * site_unreadable: the client's own website showed almost no words, so nothing is said about what it lacks; failed.
   */
  status: "compared" | "no_page" | "unreadable" | "site_unreadable" | "failed";
  page?: { url: string; title: string | null };
  theirPassage?: string | null;
  missing?: MissingFact[];
  clientUrl?: string | null;
  clientPassage?: string | null;
  /** Paste-ready, in the question's language; a number not on the client's site is a blank "[…]". */
  fix?: string | null;
}

/** A fact a rival's cited page states and the client's site doesn't, named in the three languages, with the page's words. */
export interface MissingFact {
  fact: ThreeLanguages;
  quote: string;
}

/**
 * Where the weekly report goes after each run (Hisobotlar): a Telegram chat tied to the project through our
 * bot, an email address, in which language, and on the agency plan under the agency's name.
 */
export interface ReportSettings {
  /** The chat the bot sends to, once someone started the bot from the project's link; null until then. */
  telegramChat: string | null;
  /** Where the report is emailed; "" for nowhere. */
  email: string;
  language: "uz" | "ru" | "en";
  /** The agency plan's own name on the report, in place of ours; "" for ours. */
  agencyName: string;
}

/** Only what changed; `telegram` ties a chat through the bot or lets it go. */
export type UpdateReportSettingsRequest = Partial<Pick<ReportSettings, "email" | "language" | "agencyName">> & {
  telegram?: "connect" | "disconnect";
};

/** Narrows a report to some of the project's prompts; scores are computed over those only. */
export interface ReportFilters {
  language?: PromptLanguage;
  topic?: string;
  /** One assistant's answers alone ("chatgpt", "gemini"); left out: every assistant together. */
  engine?: string;
}

/** An assistant that answered in the latest check, with how many answers it gave. */
export interface ReportEngine {
  engine: string;
  name: string;
  answers: number;
}

// One check's data object and its metrics (report spec §10, Phase 0 item 0.1): `GET /projects/{id}/waves/{runId}`,
// readable by the report's link; runId "latest" is the newest finished check. The report shows the metrics' numbers
// and works out none of its own.

/** What a call was told of where the customer is: `set` only when the search itself took it. */
export interface WaveLocation {
  country: string | null;
  city: string | null;
  timezone: string | null;
  set: boolean;
  /** "user_location" (ChatGPT's search tool), "instruction" (a sentence in Gemini's instructions), or null. */
  how: string | null;
}

export type SlotStatus = "planned" | "completed" | "failed" | "excluded";

/** Why a slot failed or was left out: "free_check_subset", "error", "empty_answer", "not_logged", "not_planned". */
export type SlotReason = string;

/** One planned call to an assistant: a question, an assistant, a run, what it was told and what came of it. */
export interface WaveSlot {
  id: string;
  prompt_id: string;
  group: "discovery" | "branded";
  lang: string;
  engine: string;
  model: string | null;
  /** "api_web_search" (ChatGPT) or "api_grounded" (Gemini with Google Search). */
  surface: string | null;
  location: WaveLocation;
  run_index: number;
  status: SlotStatus;
  reason: SlotReason | null;
  attempts: number;
  answer_id: string | null;
  searched: boolean | null;
  cost_usd: number | null;
  /** Rebuilt from what an older check saved, before the slot log (21 Nov 2026). */
  reconstructed: boolean;
}

export interface Wave {
  schema_version: number;
  project: {
    id: string;
    brand: { id: string; name: string; aliases: string[]; domains: string[] };
    competitors: { id: string; name: string; aliases: string[]; domains: string[] }[];
    category: string;
    /** The country the business serves, two letters. */
    market: string;
    city: string;
  };
  wave: {
    id: string;
    /** Its place among the project's finished checks, from 1. */
    number: number;
    is_baseline: boolean;
    kind: string;
    collected_at: string;
    runs_per_prompt: number;
    settings_hash: string;
    reconstructed: boolean;
  };
  prompts: { id: string; text: string; lang: string; group: "discovery" | "branded"; topic: string; version: number }[];
  slots: WaveSlot[];
  answers: {
    id: string;
    prompt_id: string;
    slot_id: string | null;
    lang: string;
    engine: string;
    model: string | null;
    /** The answer's run of its question on its assistant, from 1. */
    run_index: number;
    collected_at: string;
    text: string;
    searches: string[];
    searched: boolean;
    mentions: { brand_id: string | null; name: string; tracked: boolean; position: number; tone: string; recommended: boolean }[];
    citations: { url: string; title: string | null; domain: string }[];
  }[];
  /** The sites the buyers' answers cite, with their kind and whether they list the client (as typed before item 0.4). */
  domains: { domain: string; type: DomainType; control: DomainControl; route: DomainRoute | null; review: DomainReview; listed: boolean; rivals: string[] }[];
  branded: { engine: string; lang: string; question: string; known: string; statements: Record<string, unknown>[] }[];
}

/** How a set of slots came out. */
export interface SlotTally {
  slots: number;
  /** Put to the assistant: every slot but the ones left out. */
  asked: number;
  completed: number;
  failed: number;
  excluded: number;
  /** Planned and never closed: the check stopped before the call came back. */
  unfinished: number;
  failed_reasons: Record<SlotReason, number>;
  excluded_reasons: Record<SlotReason, number>;
}

/** One assistant on the scope card: its models, surface, location, slots and searched answers. */
export interface ScopeEngine extends SlotTally {
  engine: string;
  models: string[];
  surface: string | null;
  location: WaveLocation | null;
  location_varies: boolean;
  /** Of its completed answers, how many came with a web search behind them. */
  searched: number;
}

/** The scope card (report spec §4.0), counted from the slot log only. */
export interface WaveScope {
  wave: { number: number; is_baseline: boolean; kind: string; collected_at: string; settings_hash: string; reconstructed: boolean };
  engines: ScopeEngine[];
  /** Assistants not checked yet: "google_ai_overviews", "yandex". */
  not_tracked: string[];
  prompts: { discovery: number; by_language: Record<string, number>; branded: number; howto: number };
  runs_per_prompt: number;
  /** The buyers' questions' slots. */
  slots: SlotTally;
  answers_by_language: Record<string, number>;
  /** The brand questions' slots, kept apart from every number about the buyers' questions. */
  branded: SlotTally & { engines: (SlotTally & { engine: string })[] };
  brands_tracked: number;
  /** Businesses the buyers' answers name that the project doesn't track, not reviewed. */
  other_names: number;
}

/**
 * The headline (report spec rule 1, §4.1; Phase 0 item 0.2): the buyers' answers naming the client out of all of
 * them, and the questions it was named in at least once. Counts only, never a score.
 */
export interface WaveVisibility {
  answers: number;
  named: number;
  /** Fewer than `small_sample_below` answers (20): the count carries the "small sample" badge (spec §6.3). */
  small_sample: boolean;
  small_sample_below: number;
  /** Questions with at least one completed answer. */
  prompts: number;
  prompts_named: number;
  /** Questions where a tracked competitor was named and the client never was. */
  prompts_only_rivals: number;
  /** Answers citing any site, and of them those citing the client's own (spec §6.3, client citation rate). */
  cited_answers: number;
  client_cited: number;
}

export type ToneSummary = Tone | "mixed";

/** One tracked brand over the buyers' answers (spec §4.4, §6.3). */
export interface WaveBrand {
  id: string;
  name: string;
  own: boolean;
  /** Answers naming it, out of `answers`. */
  named: number;
  answers: number;
  prompts_named: number;
  mentions: number;
  /** Its place among the brands by `named`; brands named equally often share it (`tied`). Null when named nowhere. */
  rank: { place: number; tied: number } | null;
  /** Counted per mention; a word for them all (`summary`) only from 3 mentions; nothing at none. */
  tone: { mentions: number; counts: Partial<Record<Tone, number>>; summary: ToneSummary | null };
  /** A place only where an answer names it in a numbered list: in `numbered` of the `named` answers, their median item. */
  position: { numbered: number; named: number; median: number | null };
  /** Answers citing a site of its own. */
  cited: number;
}

export interface WaveBrands {
  /** The client first, then its competitors in the project's order. */
  rows: WaveBrand[];
  /** Who is named most: one brand leads only when it is alone here; empty when nobody is named. */
  leaders: string[];
  /** The strongest competitor on each count, every one of them on a tie; none at 0. */
  rivals_top: Record<"named" | "prompts_named" | "mentions" | "cited", { value: number; ids: string[] }>;
  /** A brand's tone is summed up in a word only from this many mentions (3). */
  tone_summary_from: number;
  /** Shown only from `minimum` mentions of the tracked brands in all; under it, `shares` is null. */
  share_of_voice: { mentions: number; minimum: number; shown: boolean; shares: Record<string, { k: number; n: number }> | null };
}

/** Who is named most among some answers: every brand at the top count; none at 0. */
export interface WaveTop {
  value: number;
  ids: string[];
}

/** One assistant over its own buyers' answers (Phase 0 item 0.3). */
export interface WaveAssistant {
  engine: string;
  answers: number;
  /** Those naming the client. */
  named: number;
  /** Who it names most, the client among them. */
  top: WaveTop;
}

/** A topic, or a question language, over its buyers' answers: the client's count beside the competitors named most. */
export interface WaveGroup {
  key: string;
  prompts: number;
  answers: number;
  named: number;
  rivals: WaveTop;
}

/** A cited site in the report: its type, who controls and typed it, whether it lists the client. */
export interface WaveSource {
  domain: string;
  type: DomainType;
  control: DomainControl;
  review: DomainReview;
  route: DomainRoute | null;
  listed: boolean;
  /** How many tracked competitors are beside it. */
  rivals: number;
  /** The answers citing it, once an answer. */
  cited: number;
  /** A placement target (spec §7): the only kind of site a "get listed" action may name. */
  target: boolean;
}

/** The cited sites (spec §4.6, §6.3): each counted once per answer, over the answers that cite any site. */
export interface WaveSources {
  cited_answers: number;
  sites: number;
  rows: WaveSource[];
  /** The sites by type, counted in sites. */
  types: Partial<Record<DomainType, number>>;
  /** The placement targets' domains, the most cited first. */
  targets: string[];
}

/** The brand-question check (spec §4.7), apart from every count of the buyers' answers. */
export interface WaveClaims {
  answers: number;
  statements: number;
  verified: number;
  unverified: number;
  contradicted: number;
}

/**
 * The report's top finding (spec §4.1, §4.14, Phase 0 item 0.5): one buyer question and every answer to it.
 * `competitor`: tracked competitors named where the client isn't; `shared`: beside the client; `client`: the
 * client alone; `open`: no tracked business named in any answer (no question then).
 */
export interface WaveTopFinding {
  kind: "competitor" | "shared" | "client" | "open";
  prompt_id: string | null;
  /** Its answers' ids, ChatGPT's first. */
  answers: string[];
  /** The competitors named in them, the most named first. */
  named: string[];
  client_named: number;
  of: number;
}

/** Who holds a buyer question's answers (spec §4.1's shelf, the Free Snapshot, Phase 0 item 0.8). */
export type ShelfStatus = "competitor" | "client" | "shared" | "open";

export interface WaveShelf {
  questions: { prompt_id: string; status: ShelfStatus; answers: number; named: number; rivals: number }[];
  counts: Record<ShelfStatus, number>;
}

/** Every business the buyers' answers name, each once an answer; untracked ones by their spelling (0.8). */
export interface WaveProviders {
  answers: number;
  rows: { key: string; name: string; tracked: boolean; own: boolean; answers: number }[];
}

export interface WaveMetrics {
  scope: WaveScope;
  visibility: WaveVisibility;
  brands: WaveBrands;
  assistants: WaveAssistant[];
  topics: WaveGroup[];
  languages: WaveGroup[];
  sources: WaveSources;
  claims: WaveClaims;
  top_finding: WaveTopFinding | null;
  shelf: WaveShelf;
  providers: WaveProviders;
  /** Spec §6.3's topic ranking (0.9): which topics have enough answers to judge, and whether they may be ranked. */
  topic_ranking: { ranked: boolean; eligible: string[]; topics: number; largest: number; minimum_topics: number; minimum_answers: number };
}

/** GET /snapshots/{firstRunId}: the free first check's one page (0.8), with its Telegram digest. */
export interface SnapshotResponse extends WaveResponse {
  projectId: string;
  runId: string;
  digest: string;
}

/** GET /projects/{id}/waves/{runId}/digest: a check's six lines for Telegram (0.8). */
export interface DigestResponse {
  runId: string;
  text: string;
}

export interface WaveResponse {
  wave: Wave;
  metrics: WaveMetrics;
}

// Request bodies

export type NewBrand = Omit<Brand, "id">;

export interface CreateProjectRequest {
  name: string;
  aliases: string[];
  domain: string;
  category: string;
  /** "" when the business serves its whole country. */
  city: string;
  /** Two-letter country code; Uzbekistan when left out. */
  country?: string;
  competitors: NewBrand[];
  /** Optional first question set, e.g. the questions of the free check. */
  prompts?: CreatePromptRequest[];
  /** The questions that names the business, as left in the setup. Left out: the general two. []: none. */
  brandQuestions?: BrandQuestion[];
  /** Brand profile from onboarding; the new-project form leaves them out. */
  description?: string;
  services?: string[];
  /**
   * The account's first run, when the setup was filled in from it: its answers become the project's first
   * check for the questions that were kept, so the dashboard opens on numbers and nothing is asked twice.
   */
  firstRunId?: string;
}

/** POST /projects: the new project and the run that checks its prompts for the first time. */
export interface CreateProjectResponse {
  project: Project;
  /** Poll GET /runs/{id}/progress; null when the project was created without prompts. */
  runId: string | null;
}

/**
 * Starts tracking a brand as a competitor, usually one of the report's untracked brands. Only the name is
 * needed: the backend fills in the spellings and the website it knows from the answers that name it.
 */
export interface AddCompetitorRequest {
  name: string;
  aliases?: string[];
  domain?: string;
}

/** Hides an untracked brand from the suggestions, or shows it again. */
export interface DismissBrandRequest {
  name: string;
  dismissed: boolean;
}

/** `location` left out: the project's city. */
export type CreatePromptRequest = Pick<Prompt, "text" | "language" | "topic"> & { location?: string };

/** Several questions at once: the lines of the Add window, or a file's first column. All are added, or none. */
export interface CreatePromptsRequest {
  prompts: CreatePromptRequest[];
}

export type UpdatePromptRequest = CreatePromptRequest;

/** Archive a question (stop asking it) or track it again. */
export interface ArchivePromptRequest {
  archived: boolean;
}

/** Several questions at once: archive them, track them again, move them to a topic; or one question's tags or fact-checking. */
export interface UpdatePromptsRequest {
  ids: string[];
  archived?: boolean;
  topic?: string;
  /** Replaces their tags. */
  tags?: string[];
  factCheck?: boolean;
}

/** A topic's name: a new topic, or a new name for one. */
export interface TopicRequest {
  name: string;
}

/**
 * Why a question is suggested: from the business's services and topics ("profile"), from the web searches
 * ChatGPT ran for the tracked questions ("searches"), from Discovery ("discovery"), or from keywords the
 * client imported ("keywords").
 */
export type SuggestionSource = "profile" | "searches" | "discovery" | "keywords";

/** A question the project doesn't track yet, offered on the Questions page to track or reject. */
export interface SuggestedPrompt {
  id: string;
  text: string;
  language: PromptLanguage;
  /** One of the project's topics, or a topic it doesn't have yet (a suggested topic). */
  topic: string;
  source: SuggestionSource;
  /** ISO 8601: when it was suggested. */
  createdAt: string;
}

/** Suggestions to track or to reject, several at once. */
export interface SuggestionIdsRequest {
  ids: string[];
}

/** "Suggest more": questions for one topic (one of the project's or a suggested one), or for all of them. */
export interface SuggestMoreRequest {
  topic?: string;
}

/**
 * Discovery, after Peec's: what the business sells, who buys it, anything else to follow, and in which
 * languages to ask. The services and customer types are saved to the project.
 */
export interface DiscoverPromptsRequest {
  services: string[];
  customers: string[];
  context: string;
  languages: PromptLanguage[];
}

/** Keywords from a file (an SEO tool's export, first column): the backend makes questions customers ask about them. */
export interface ImportKeywordsRequest {
  keywords: string[];
}

/** Several actions at once: "Accept all", "Decline all", or the rows picked. */
export interface UpdateActionsRequest {
  ids: string[];
  status: ActionStatus;
}

/**
 * Peec's "Add content": a page of the client's website (its address) or its text (a Markdown or text
 * file), what kind of page it is and the topic it should win. The backend reads it and writes an action
 * with a brief.
 */
export interface AddContentActionRequest {
  url?: string;
  document?: string;
  pageType: PageType;
  topic: string;
}

/** Either field or both; what's left out stays as it was. */
export interface UpdateActionRequest {
  status?: ActionStatus;
  /** Replaces the checked steps (indexes below ACTION_STEP_COUNT). */
  stepsDone?: number[];
}

export interface SendCodeRequest {
  email: string;
}

export interface SendCodeResponse {
  /** Seconds until another code can be requested. */
  resendIn: number;
}

export interface VerifyCodeRequest {
  email: string;
  code: string;
}

/** Fields the Telegram Login Widget returns; the backend checks `hash` with the bot token. */
export interface TelegramAuthRequest {
  id: number;
  first_name: string;
  last_name?: string;
  username?: string;
  photo_url?: string;
  auth_date: number;
  hash: string;
}

export type DemoSector = "clinic" | "real_estate" | "education" | "retail" | "other";

/** "Book a demo" form on the landing page. */
export interface DemoRequest {
  name: string;
  /** E.164, e.g. "+998901234567". */
  phone: string;
  sector: DemoSector;
  /** What is asked for when it isn't a demo: "First Audit · <brand>" from a Free Snapshot. */
  about?: string;
}

/** A question, bug report or idea sent from the in-app help panel. */
export interface SupportMessage {
  text: string;
}

export interface SnapshotRequest {
  domain: string;
  /** Optional: when omitted, the backend works them out from the website. */
  category?: string;
  city?: string;
}

// The contract names Snapshot without fields. Assumed shape: a smaller Report
// for a brand that has no project yet (10 prompts).
export interface Snapshot {
  id: string;
  domain: string;
  category: string;
  city: string;
  method: ReportMethod;
  brand: Brand;
  competitors: Brand[];
  scores: BrandScore[];
  prompts: PromptResult[];
  topSources: Source[];
  /** What the backend found on the website; null when it couldn't be read. */
  siteChecks: SiteCheckResult[] | null;
}

/** A new account's first run: a website in, the assistants asked, the first statistics out. */
/**
 * `ready`: the website is read and the draft waits for the owner (`FirstRunDraft`); nobody is asked until
 * they confirm it (`confirmFirstRun`).
 */
/** `waiting`: confirmed past the day's free checks, in the queue until the team runs it (its report is emailed). */
export type FirstRunStatus = "queued" | "reading_site" | "ready" | "waiting" | "asking" | "reading_answers" | "done" | "failed";

/** What a first run read from the website, for the owner to correct before the check: GET /first-runs/{id}/draft. */
export interface FirstRunDraft {
  id: string;
  domain: string;
  name: string;
  aliases: string[];
  category: string;
  /** Two-letter country code. */
  country: string;
  city: string;
  description: string;
  services: string[];
  /** `logo`: the icon the competitor's website names, when the search found one. */
  competitors: (CompetitorSuggestion & { logo?: string | null })[];
  questions: PromptSuggestion[];
  /** The general ones first, then the ones written for this business. */
  brandQuestions: BrandQuestion[];
  /** How many customers' questions a first check asks. */
  maxQuestions: number;
  /** The day's free checks are taken: confirming puts the check in the queue, and its report is emailed. */
  queue: boolean;
  /** False when the competitors are the profile's own, not a web search's (the search is skipped once the day's free checks are taken). */
  competitorsSearched: boolean;
  /** Development only: a saved check's business, not the website typed. */
  replayed: boolean;
  /**
   * Where the market came from (25 Nov 2026): the owner's pick at step 1, the website's own text, or Uzbekistan for want
   * of either. A draft from before reads "owner": step 1's list started on Uzbekistan.
   */
  countryFrom: "owner" | "site" | "default";
  /** The country the website's own text shows its customers are in; "" when it shows none. */
  siteCountry: string;
  /** How many words the website's pages gave, and whether that was almost none (its text only with JavaScript). */
  siteWords: number | null;
  thin: boolean;
}

/** What a running check has so far, counted from the answers' own words: GET /first-runs/{id}/partial. */
export interface FirstRunPartial {
  brand: string;
  answered: number;
  total: number;
  /** The client and the competitors it confirmed, each with the answers in hand that name it. */
  brands: { name: string; isYou: boolean; named: number }[];
  sites: { domain: string; count: number }[];
  pages: { url: string; title: string | null; count: number }[];
  /** The latest first; `text` is the answer's beginning. */
  answers: { question: string; engine: string; name: string; text: string; named: boolean }[];
}

/** The draft as the owner left it: POST /first-runs/{id}/start. The check asks exactly this. */
export type FirstRunConfirm = Omit<CreateProjectRequest, "firstRunId"> & { /** The page's language: a queued check's email is written in it. */ language?: string };

export interface FirstRunRequest {
  domain: string;
  /** The company's name as the owner writes it; left out, the backend reads it from the website. */
  name?: string;
  /** The country the business serves, as a two-letter code; left out, the backend reads it from the website. */
  country?: string;
}

export interface FirstRun {
  id: string;
  /** Normalized, e.g. "oqtabassum.uz". */
  domain: string;
  status: FirstRunStatus;
  /** Answers collected so far, of `total` (questions × assistants; 0 until the questions are written). */
  answered: number;
  total: number;
  /** Why it failed, as a code ("site_unreadable", "no_engines", "internal"); null otherwise. */
  error: string | null;
  /** A `waiting` check only: its place in the queue, from 1, and the address its report is emailed to. */
  place?: number;
  email?: string;
  /** A `done` check: the project it saved itself as when it ended (null when it couldn't, and its page saves it). */
  projectId?: string | null;
}

type ThreeLanguages = Record<"uz" | "ru" | "en", string>;

/** A question that names the business, asked beside the customers' questions and kept out of the scores. */
export interface BrandQuestion {
  text: string;
  language: PromptLanguage;
}

/** One assistant's answer to a question that names the business, as statements checked against its website. */
export interface BrandView {
  engine: string;
  name: string;
  language: PromptLanguage;
  question: string;
  /** Describes this business; describes another with a similar name; or finds nothing. */
  known: "knows" | "confuses" | "unknown";
  statements: {
    topic: "what" | "prices" | "place" | "contacts" | "reputation" | "other";
    text: ThreeLanguages;
    /** Against the website's text: says the same, says otherwise, or says nothing about it. */
    check: "confirmed" | "contradicted" | "unverified";
    /** What the website says, for a contradicted statement. */
    correct: ThreeLanguages | null;
  }[];
  citations: Citation[];
}

/** The first statistics: the free check's `Snapshot` and what a first run adds to it. */
export interface FirstRunResult extends Snapshot {
  /** The country the website mainly serves, as a two-letter code. */
  country?: string;
  /** A sentence or two on the business, read from its website; "" if none. */
  description: string;
  services: string[];
  /** The same scores for each assistant asked, over its own answers. */
  engines: { engine: string; name: string; answers: number; scores: BrandScore[] }[];
  /** Brand id → the answers that recommend it. */
  recommended: Record<string, number>;
  /** What the counts mean and what to do first, worded by a model from them, per interface language. */
  conclusion?: Record<"uz" | "ru" | "en", string> | null;
  /** What each assistant says when asked about the business by name; absent on runs made before 15 Nov 2026. */
  brandView?: BrandView[];
  /** The brand questions offered in the setup: the general ones (`asked` in this check), then ones written for this business. */
  brandQuestions?: (BrandQuestion & { asked: boolean })[];
  /** All answers collected. */
  answers: number;
  /** Development only: a saved run shown again, so the numbers are not this website's. */
  replayed?: boolean;
}

// Onboarding: the backend reads the website, then suggests competitors and questions.
// Everything it returns is shown as editable, pre-filled fields.
export interface AnalyzeSiteRequest {
  domain: string;
}

/** What the backend found on the website. */
export interface SiteAnalysis {
  /** Normalized, e.g. "oqtabassum.uz". */
  domain: string;
  name: string;
  /** Other spellings it found, Latin and Cyrillic. */
  aliases: string[];
  category: string;
  city: string;
  /** Two-letter country code; Uzbekistan when left out. */
  country?: string;
  /** A sentence or two on what the business does, written from its website. */
  description: string;
  /** What it offers, as named on the website, most important first. */
  services: string[];
}

export interface SuggestCompetitorsRequest {
  domain: string;
  name: string;
  category: string;
  city: string;
}

/** 4–6 of them, most relevant first. */
export type CompetitorSuggestion = NewBrand;

export interface SuggestPromptsRequest {
  name: string;
  category: string;
  city: string;
  /** The services the client kept; questions are suggested for them first. */
  services?: string[];
}

/** About 20 buyer questions, Uzbek and Russian, each with a topic. */
export type PromptSuggestion = CreatePromptRequest;

/** queued → running (asking ChatGPT) → analyzing (parsing answers, scores) → done; or failed. */
export type RunStatus = "queued" | "running" | "analyzing" | "done" | "failed";

/** One run asks every prompt `samples` times, so `total` = prompts × samples. */
export interface RunProgress {
  id: string;
  projectId: string;
  status: RunStatus;
  /** Answers collected so far. */
  answered: number;
  total: number;
}

/**
 * The team's admin page (25 Nov 2026; `backend/app/superadmin.py`), behind its own login (`geo_admin`): who is logged in
 * and how many free checks wait.
 */
export interface AdminMe {
  username: string;
  waiting: number;
}

/** A project, as the admin page lists it: whose, its plan, its checks, and its latest check's headline count. */
export interface AdminProject {
  id: string;
  name: string;
  domain: string;
  /** The account's email; null when the account is gone. */
  owner: string | null;
  /** One of the team's accounts (`TEAM_EMAILS`): its checks aren't counted in the day's limit. */
  team: boolean;
  createdAt: string;
  plan: Plan;
  paid: boolean;
  billingStatus: string | null;
  country: string;
  /** Finished checks. */
  checks: number;
  latestCheckAt: string | null;
  /** The latest check's buyer answers, and those naming the business: the report's headline. */
  answers: number;
  named: number;
  /** The free check the project was saved from: its snapshot's address. */
  firstRunId: string | null;
}

export interface AdminUser {
  id: string;
  email: string;
  name: string | null;
  team: boolean;
  createdAt: string;
  /** When the latest session began; null once the account logged out of every session. */
  lastLoginAt: string | null;
  projects: { id: string; domain: string }[];
  /** Free checks the account started, and the latest one. */
  firstChecks: number;
  freeCheck: { id: string; domain: string; status: FirstRunStatus; at: string } | null;
}

export interface AdminOverview {
  users: { total: number; week: number };
  projects: { total: number; week: number };
  /** Free checks in the last 24 hours (the team's aren't counted), and the day's limit. */
  checksToday: number;
  checksADay: number;
  firstChecks: { done: number; failed: number; waiting: number; running: number; preparing: number };
  /** In US dollars: every free check, those of the last 7 days, and the paid plans' checks. */
  cost: { freeChecks: number; freeChecksWeek: number; planChecks: number };
  latestProjects: AdminProject[];
  latestUsers: AdminUser[];
}

export interface AdminWaitingCheck {
  id: string;
  /** Its place in the queue, from 1. */
  place: number;
  domain: string;
  email: string | null;
  team: boolean;
  /** When it joined the queue. */
  since: string;
  /** The language of its page, and so of the email that tells it the results are ready. */
  language: PromptLanguage;
  name: string;
  questions: number;
}

export interface AdminRunningCheck {
  id: string;
  domain: string;
  email: string | null;
  status: "asking" | "reading_answers";
  answered: number;
  total: number;
  since: string;
}

export interface AdminQueue {
  waiting: AdminWaitingCheck[];
  running: AdminRunningCheck[];
  /** What a check costs, from the latest ones done, in US dollars. */
  checkUsd: number;
  checksToday: number;
  checksADay: number;
}
